// HasReseller applies the HasEdge predicate on the "reseller" edge.
func HasReseller() predicate.ResellerPlan {
	return predicate.ResellerPlan(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.O2O, true, ResellerTable, ResellerColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasResellerWith applies the HasEdge predicate on the "reseller" edge with a given conditions (other predicates).
func HasResellerWith(preds ...predicate.Reseller) predicate.ResellerPlan {
	return predicate.ResellerPlan(func(s *sql.Selector) {
		step := newResellerStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.ResellerPlan) predicate.ResellerPlan {
	return predicate.ResellerPlan(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.ResellerPlan) predicate.ResellerPlan {
	return predicate.ResellerPlan(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.ResellerPlan) predicate.ResellerPlan {
	return predicate.ResellerPlan(sql.NotPredicates(p))
}
